#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-30

# Unit test for src/skills/verify/scripts/assert-evidence.sh (#3263)
#
# The verify skill's background-task contract lived in prose; this script is
# its executable form. Cases pin every outcome, with the EVIDENCE case as the
# control that a non-empty, banner-bearing, finished log is still gradable.
# Also pins that SKILL.md wires the script and names COULD-NOT-OBSERVE.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
CHECK="$REPO_ROOT/src/skills/verify/scripts/assert-evidence.sh"
SKILL="$REPO_ROOT/src/skills/verify/SKILL.md"

if [[ ! -x "$CHECK" ]]; then
    echo "FAIL: $CHECK not found or not executable" >&2
    exit 1
fi

TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork.XXXXXX")"
SLEEPER=""
cleanup() {
    rm -rf "$TMP"
    if [[ -n "$SLEEPER" ]]; then
        # silent: post-cleanup
        kill "$SLEEPER" 2>/dev/null || true
        # silent: post-cleanup
        wait "$SLEEPER" 2>/dev/null || true
    fi
}
trap cleanup EXIT

PASS=0
FAIL=0

assert_exit() {
    local name="$1" expected="$2" actual="$3"
    if [[ "$expected" -eq "$actual" ]]; then
        echo "  ✓ $name (exit=$actual)"; PASS=$((PASS + 1))
    else
        echo "  ✗ $name (expected exit=$expected, got $actual)"; FAIL=$((FAIL + 1))
    fi
}

assert_contains() {
    local name="$1" needle="$2" haystack="$3"
    if [[ "$haystack" == *"$needle"* ]]; then
        echo "  ✓ $name"; PASS=$((PASS + 1))
    else
        echo "  ✗ $name (missing: $needle in: $haystack)"; FAIL=$((FAIL + 1))
    fi
}

run() {  # $@ = args; sets OUT and RC
    set +e
    OUT="$("$CHECK" "$@" 2>&1)"; RC=$?
    set -e
}

echo "assert-evidence.sh"

# 1. 0 bytes, nobody alive: the run never happened
: > "$TMP/empty.log"
run "$TMP/empty.log" --pid 999999999
assert_exit "0-byte log + dead pid is COULD-NOT-OBSERVE" 3 "$RC"
assert_contains "outcome named" "outcome=COULD-NOT-OBSERVE" "$OUT"
assert_contains "bytes reported" "bytes=0" "$OUT"

# 2. missing file counts as 0 bytes
run "$TMP/never-created.log" --pid 999999999
assert_exit "missing log is COULD-NOT-OBSERVE" 3 "$RC"

# 3. control: banner + EXIT marker is EVIDENCE
{ echo "> orchestkit@10.0.0 test"; echo "Tests: 5 passed"; echo "EXIT=0"; } > "$TMP/good.log"
run "$TMP/good.log" --task-id b123
assert_exit "banner + EXIT marker is EVIDENCE" 0 "$RC"
assert_contains "task id recorded" "task_id=b123" "$OUT"
assert_contains "banner=yes" "banner=yes" "$OUT"

# 4. output without the runner's banner
{ echo "sh: npm: command not found"; echo "EXIT=127"; } > "$TMP/nobanner.log"
run "$TMP/nobanner.log" --pid 999999999
assert_exit "bytes without banner is NO-BANNER" 1 "$RC"
assert_contains "NO-BANNER named" "outcome=NO-BANNER" "$OUT"

# 5. 0 bytes but a live pid: still running
sleep 30 & SLEEPER=$!
: > "$TMP/running.log"
run "$TMP/running.log" --pid "$SLEEPER"
assert_exit "0-byte log + live pid is STILL-RUNNING" 4 "$RC"

# 6. banner but no EXIT marker and a live pid: still running
echo "> orchestkit@10.0.0 test" > "$TMP/partial.log"
run "$TMP/partial.log" --pid "$SLEEPER"
assert_exit "banner without EXIT marker + live pid is STILL-RUNNING" 4 "$RC"
# silent: post-cleanup
kill "$SLEEPER" 2>/dev/null || true
# silent: post-cleanup
wait "$SLEEPER" 2>/dev/null || true
SLEEPER=""

# 7. banner, no EXIT marker, nobody alive: started and never finished
run "$TMP/partial.log" --pid 999999999
assert_exit "banner without EXIT marker + dead pid is NO-BANNER (not gradable)" 1 "$RC"

# 8. json form
run "$TMP/good.log" --json
assert_exit "json form exits like the plain form" 0 "$RC"
assert_contains "json outcome" '"outcome":"EVIDENCE"' "$OUT"

# 9. usage
run
assert_exit "no logfile is usage" 2 "$RC"
run "$TMP/good.log" --pid notanumber
assert_exit "non-numeric pid is usage" 2 "$RC"
run --help
assert_exit "--help exits 0" 0 "$RC"
assert_contains "--help shows outcomes" "COULD-NOT-OBSERVE" "$OUT"

# 10. custom banner regex (pytest)
{ echo "============ test session starts ============"; echo "1 passed"; echo "EXIT=0"; } > "$TMP/pytest.log"
run "$TMP/pytest.log" --banner-re '^=+ test session'
assert_exit "custom banner regex is honoured" 0 "$RC"

echo "SKILL.md wiring"
N=$(awk '/COULD-NOT-OBSERVE/{n++} END{print n+0}' "$SKILL")
if [[ "$N" -ge 4 ]]; then echo "  ✓ SKILL.md names COULD-NOT-OBSERVE at every verdict site ($N)"; PASS=$((PASS + 1)); else echo "  ✗ SKILL.md names COULD-NOT-OBSERVE only $N times (need >= 4)"; FAIL=$((FAIL + 1)); fi
if grep -q 'assert-evidence.sh' "$SKILL"; then echo "  ✓ SKILL.md invokes assert-evidence.sh"; PASS=$((PASS + 1)); else echo "  ✗ SKILL.md does not invoke assert-evidence.sh"; FAIL=$((FAIL + 1)); fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ "$FAIL" -eq 0 ]]
